window.AUTH=window.AUTH||{};window.AUTH["23-191"]={"d":"23-191","id":"2024/23-191","n":"Williams v. Reed","briefs":[{"k":"petitioner","label":"Brief of petitioners Nancy Williams, et al.","date":"2024-04-11","url":"https://www.supremecourt.gov/DocketPDF/23/23-191/307337/20240411113136781_23-191%20ts.pdf","side":"pet","n":31},{"k":"respondent","label":"Brief of respondent Fitzgerald Washington, Alabama Secretary of Labor","date":"2024-06-25","url":"https://www.supremecourt.gov/DocketPDF/23/23-191/315682/20240625131142924_2024.06.24%20Nancy%20Williams%20Resp.%20Br.%20FINAL.pdf","side":"res","n":109},{"k":"reply","label":"Reply of petitioners Nancy Williams, et al.","date":"2024-07-25","url":"https://www.supremecourt.gov/DocketPDF/23/23-191/320744/20240725102156134_23-191%20rb.pdf","side":"pet","n":18}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r11_2b8e.pdf","tr":true,"items":[{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"0":"2, 13, 17, 29, 30","1":"47"}},{"t":"case","label":"Allen v. McCurry","cite":"449 U.S. 90","y":1980,"id":"1980/79-935","sc":1,"sum":"The Court of Appeals erred in holding that respondent's inability to obtain federal habeas corpus relief upon his Fourth Amendment claim renders the doctrine of collateral estoppel inapplicable to his § 1983 suit. Nothing in the language or legislative history of § 1983 discloses any congressional intent to deny binding effect to a state-court judgment or decision when the state court, acting within its proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"California Department of Human Resource Development v. Java","cite":"402 U.S. 121","y":1971,"id":"1970/507","sc":1,"sum":"Section 303 (a) (1) of the Social Security Act requires a method of administration \"reasonably calculated to insure full payment of unemployment compensation when due.\" In light of the intent of Congress to make payments available at the earliest stage of unemployment as is administratively feasible, in order to provide a substitute for wages, the language \"when due\" must be construed to mean when benefits are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"FBI v. Fikre","cite":"144 S. Ct. 771","y":2024,"url":"https://www.courtlistener.com/c/S.%20Ct./144/771/","sc":1,"by":{"0":"7"}},{"t":"case","label":"Felder v. Casey","cite":"487 U.S. 131","y":1988,"id":"1987/87-526","sc":1,"op":11,"ar":48,"sum":"Because the Wisconsin notice-of-claim statute conflicts in both its purpose and effects with § 1983's remedial objectives, and because its enforcement in state-court actions will frequently and predictably produce different outcomes in § 1983 litigation based solely on whether the claim is asserted in state or federal court, it is pre-empted pursuant to the Supremacy Clause when the § 1983 action is brought in a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 15, 16, 19, 21-27, 31, 32, 36, 37, 39","1":"24-29, 33, 35-29, 40, 43","2":"1, 4, 7-14, 17, 18, 20-22, 25"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"35, 37","1":"19"}},{"t":"case","label":"Haywood v. Drown","cite":"556 U.S. 729","y":2009,"id":"2008/07-10374","sc":1,"op":35,"ar":16,"sum":"The Court found that prohibiting civil claims against correction officers in their official capacities violated the Supremacy Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"29, 39","1":"27-33, 42, 44, 45","2":"13, 18, 19, 21-23"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"0":"34","1":"37","2":"6"}},{"t":"case","label":"Howlett ex rel. Howlett v. Rose","cite":"496 U.S. 356","y":1990,"id":"1989/89-5383","sc":1,"op":11,"ar":7,"sum":"A state-law \"sovereign immunity\" defense is not available to a school board in a § 1983 action brought in a state court that otherwise has jurisdiction when such defense would not be available if the action were brought in a federal forum.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 16, 17, 28-31","1":"22-25, 27-29, 33, 40-44","2":"2-4, 13, 17-19, 23"}},{"t":"case","label":"James v. City of Boise","cite":"577 U.S. 306","y":2016,"id":"2015/15-493","sc":1,"sum":"The Court held that the Idaho Supreme Court erred by concluding that the U.S. Supreme Court’s decision in Hughes v. Rowe did not bind state courts.","sumSrc":"Oyez","by":{"0":"3, 21"}},{"t":"case","label":"Johnson v. Fankell","cite":"520 U.S. 911","y":1997,"id":"1996/96-292","sc":1,"op":1,"ar":2,"sum":"In unanimous opinion delivered by John Paul Stevens, the Court held that defendants in a state-court section 1983 action do not have a federal right to an interlocutory appeal from a denial of qualified immunity. The Court reasoned that in construing state rules allowing appeals from final judgments, state courts did not need to accept the federal definition of a \"final decision\" within the meaning of federal law.","sumSrc":"Oyez","by":{"0":"32, 33","1":"26, 27, 33, 42, 44","2":"16, 17"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Knick v. Township of Scott","cite":"588 U.S. 180","y":2019,"id":"2018/17-647","sc":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35","2":"6"}},{"t":"case","label":"Maine v. Thiboutot","cite":"448 U.S. 1","y":1980,"id":"1979/79-838","sc":1,"sum":"Yes to both. Section 1983 encompasses claims based on purely statutory violations of federal law, and section 1988 authorizes attorney's fees to the prevailing party in such actions, whether brought in federal or state court.","sumSrc":"AI-generated brief","by":{"0":"40"}},{"t":"case","label":"McNeese v. Board of Education","cite":"373 U.S. 668","y":1963,"id":"1962/480","sc":1,"sum":"The Court held that exhausting state remedies was not a prerequisite to bringing a suit under the Civil Rights Act.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Mitchum v. Foster","cite":"407 U.S. 225","y":1972,"id":"1971/70-27","sc":1,"sum":"Title 42 U. S. C.'§ 1983, which authorizes a suit in-equity to redress the deprivation under color of state law \"of any rights, privileges, or immunities secured by theConstitution.. '.,\" is within that exception of the federal anti-injunction statute, 28 U. S. C. § 2283, that provides 'that a federal court may not enjoin state court proceedings \"except as. expressly authorized by Act of Congress.\" And in this § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"0":"3-4, 40"}},{"t":"case","label":"Pakdel v. City & County of San Francisco","cite":"594 U.S. 474","y":2021,"url":"https://supreme.justia.com/cases/federal/us/594/474/","sc":1,"by":{"0":"14, 35","2":"5-6"}},{"t":"case","label":"Patsy v. Board of Regents","cite":"457 U.S. 496","y":1982,"id":"1981/80-1874","sc":1,"op":3,"ar":15,"sum":"Exhaustion of state administrative remedies is not a prerequisite to an action under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 3, 12, 14, 15, 18-20, 23-26, 34-36, 39","1":"16, 21, 30, 33-38","2":"1, 2, 4-7, 22"}},{"t":"case","label":"Porter v. Nussle","cite":"534 U.S. 516","y":2002,"id":"2001/00-853","sc":1,"sum":"The Court held that the PLRA's exhaustion requirement applies to all inmate suits about prison life, whether they involve general circumstances or particular episodes, and whether they allege excessive force or some other wrong. The Court rejected Nussle's argument that Congress added the words \"prison conditions\" to exempt excessive force claims.","sumSrc":"Oyez","by":{"0":"34-35"}},{"t":"case","label":"Quick v. Utotem of Alabama, Inc.","cite":"365 So. 2d 1245","y":1979,"court":"Ala. Civ. App.","url":"https://www.courtlistener.com/c/So.%202d/365/1245/","by":{"0":"5"}},{"t":"case","label":"Reed v. Goertz","cite":"598 U.S. 230","y":2023,"id":"2022/21-442","sc":1,"op":1,"sum":"When a prisoner pursues state post-conviction DNA testing through the state-provided litigation process, the statute of limitations for a 42 U. S. C. §1983 procedural due process claim begins to run when the state litigation ends, in this case when the Texas Court of Criminal Appeals denied Reed’s motion for rehearing.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35","1":"37"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Wilder v. Virginia Hospital Ass’n","cite":"496 U.S. 498","y":1990,"id":"1989/88-2043","sc":1,"op":6,"sum":"In a 5-to-4 decision, the Court held that the Boren Amendment clearly established a right to reasonable and adequate reimbursement rates for the hospitals.","sumSrc":"Oyez","by":{"0":"34","1":"37"}},{"t":"case","label":"Wright v. City of Roanoke Redevelopment & Housing Authority","cite":"479 U.S. 418","y":1987,"id":"1986/85-5915","sc":1,"sum":"The Brooke Amendment to the Housing Act of 1937 imposed a ceiling on rents charged to low-income persons living in public housing projects, and, as later amended, provides that a low-income family \"shall pay as rent\" a specified percentage of its income. The Department of Housing and Urban Development (HUD) has consistently considered \"rent\" to include a reasonable amount for the use of utilities. Petitioners, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"37"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"0":"1","1":"47"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","subs":["(a)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"0":"32","2":"17"}},{"t":"usc","label":"42 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/42/503","subs":["(a)(1)"],"stext":{"head":"§503. State laws","paras":[[0,"(a) Provisions required"],[0,"The Secretary of Labor shall make no certification for payment to any State unless he finds that the law of such State, approved by the Secretary of Labor under the Federal Unemployment Tax Act [26 U.S.C. 3301 et seq.], includes provision for—"],[1,"(1) Such methods of administration (including after January 1, 1940, methods relating to the establishment and maintenance of personnel standards on a merit basis, except that the Secretary of Labor shall exercise no authority with respect to the selection, tenure of office, and compensation of any individual employed in accordance with such methods) as are found by the Secretary of Labor to be reasonably calculated to insure full payment of unemployment compensation when due; and"],[1,"(2) Payment of unemployment compensation solely through public employment offices or such other agencies as the Secretary of Labor may approve; and"],[1,"(3) Opportunity for a fair hearing, before an impartial tribunal, for all individuals whose claims for unemployment compensation are denied; and"],[1,"(4) The payment of all money received in the unemployment fund of such State (except for refunds of sums erroneously paid into such fund and except for refunds paid in accordance with the provisions of section 3305(b) of the Federal Unemployment Tax Act [26 U.S.C. 3305(b)]), immediately upon such receipt, to the Secretary of the Treasury to the credit of the unemployment trust fund 1 established by section 1104 of this title; and"],[1,"(5) Expenditure of all money withdrawn from an unemployment fund of such State, in the payment of unemployment compensation, exclusive of expenses of administration, and for refunds of sums erroneously paid into such fund and refunds paid in accordance with the provisions of section 3305(b) of the Federal Unemployment Tax Act [26 U.S.C. 3305(b)]: Provided, That an amount equal to the amount of employee payments into the unemployment fund of a State may be used in the payment of cash benefits to individuals with respect to their disability, exclusive of expenses of administration: Provided further, That the amounts specified by section 1103(c)(2) or 1103(d)(4) of this title may, subject to the conditions prescribed in such section, be used for expenses incurred by the State for administration of its unemployment compensation law and public employment offices: Provided further, That nothing in this paragraph shall be construed to prohibit deducting an amount from unemployment compensation otherwise payable to an individual and using the amount so deducted to pay for health insurance, or the withholding of Federal, State, or local individual income tax, if the individual elected to have such deduction made and such deduction was made under a program approved by the Secretary of Labor: Provided further, That amounts may be deducted from unemployment benefits and used to repay overpayments as provided in subsection (g): Provided further, That amounts may be withdrawn for the payment of short-time compensation under a short-time compensation program (as defined in section 3306(v) of the Internal Revenue Code of 1986): Provided further, That amounts may be withdrawn for the payment of allowances under a self-employment assistance program (as defined in section 3306(t) of the Internal Revenue Code of 1986); and"],[1,"(6) The making of such reports, in such form and containing such information, as the Secretary of Labor may from time to time require, and compliance with such provisions as the Secretary of Labor may from time to time find necessary to assure the correctness and verification of such reports; and"],[1,"(7) Making available upon request to any agency of the United States charged with the administration of public works or assistance through public employment, the name, address, ordinary occupation and employment status of each recipient of unemployment compensation, and a statement of such recipient's rights to further compensation under such law; and"],[1,"(8) Effective July 1, 1941, the expenditure of all moneys received pursuant to section 502 of this title solely for the purposes and in the amounts found necessary by the Secretary of Labor for the proper and efficient administration of such State law; and"],[1,"(9) Effective July 1, 1941, the replacement, within a reasonable time, of any moneys received pursuant to section 502 of this title, which, because of any action or contingency, have been lost or have been expended for purposes other than, or in amounts in excess of, those found necessary by the Secretary of Labor for the proper administration of such State law; and"],[1,"(10) A requirement that, as a condition of eligibility for regular compensation for any week, any claimant who has been referred to reemployment services pursuant to the profiling system under subsection (j)(1)(B) participate in such services or in similar services unless the State agency charged with the administration of the State law determines—"],[2,"(A) such claimant has completed such services; or"],[2,"(B) there is justifiable cause for such claimant's failure to participate in such services; and"],[1,"(11)(A) At the time the State agency determines an erroneous payment from its unemployment fund was made to an individual due to fraud committed by such individual, the assessment of a penalty on the individual in an amount of not less than 15 percent of the amount of the erroneous payment; and"],[1,"(B) The immediate deposit of all assessments paid pursuant to subparagraph (A) into the unemployment fund of the State.2"],[1,"(12) A requirement that, as a condition of eligibility for regular compensation for any week, a claimant must be able to work, available to work, and actively seeking work."],[0,"(b) Failure to comply; payments stopped"],[0,"Whenever the Secretary of Labor, after reasonable notice and opportunity for hearing to the State agency charged with the administration of the State law, finds that in the administration of the law there is—"],[1,"(1) a denial, in a substantial number of cases, of unemployment compensation to individuals entitled thereto under such law; or"],[1,"(2) a failure to comply substantially with any provision specified in subsection (a);"],[0,"the Secretary of Labor shall notify such State agency that further payments will not be made to the State until the Secretary of Labor is satisfied that there is no longer any such denial or failure to comply. Until he is so satisfied he shall make no further certification to the Secretary of the Treasury with respect to such State: Provided, That there shall be no finding under clause (1) until the question of entitlement shall have been decided by the highest judicial authority given jurisdiction under such State law: Provided further, That any costs may be paid with respect to any claimant by a State and included as costs of administration of its law."],[0,"(c) Denial of certification; availability of records to Railroad Retirement Board; cooperation with Federal agencies"],[0,"The Secretary of Labor shall make no certification for payment to any State if he finds, after reasonable notice and opportunity for hearing to the State agency charged with the administration of the State law—"],[1,"(1) that such State does not make its records available to the Railroad Retirement Board, and furnish to the Railroad Retirement Board at the expense of the Railroad Retirement Board such copies thereof as the Railroad Retirement Board deems necessary for its purposes;"],[1,"(2) that such State is failing to afford reasonable cooperation with every agency of the United States charged with the administration of any unemployment insurance law; or"],[1,"(3) that any interest required to be paid on advances under subchapter XII of this chapter has not been paid by the date on which such interest is required to be paid or has been paid directly or indirectly (by an equivalent reduction in State unemployment taxes or otherwise) by such State from amounts in such State's unemployment fund, until such interest is properly paid."],[0,"(d) Disclosure of unemployment compensation information; coordination with supplemental nutrition assistance program benefits agencies; non-compliance of State agency"],[0,"(1) The State agency charged with the administration of the State law—"],[1,"(A) shall disclose, upon request and on a reimbursable basis, to officers and employees of the Department of Agriculture and to officers or employees of any State supplemental nutrition assistance program benefits agency any of the following information contained in the records of such State agency—"],[2,"(i) wage information,"],[2,"(ii) whether an individual is receiving, has received, or has made application for, unemployment compensation, and the amount of any such compensation being received (or to be received) by such individual,"],[2,"(iii) the current (or most recent) home address of such individual, and"],[2,"(iv) whether an individual has refused an offer of employment and, if so, a description of the employment so offered and the terms, conditions, and rate of pay therefor, and"],[1,"(B) shall establish such safeguards as are necessary (as determined by the Secretary of Labor in regulations) to insure that information disclosed under subparagraph (A) is used only for purposes of determining an individual's eligibility for benefits, or the amount of benefits, under the supplemental nutrition assistance program established under the Food and Nutrition Act of 2008 [7 U.S.C. 2011 et seq.]."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/503?type=usc&year=mostrecent&link-type=html"},"head":"§503. State laws","tname":"The Public Health and Welfare","by":{"0":"5, 11","1":"7-8"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":67,"ar":14,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"1-3, 12, 13, 18, 22, 27, 32, 35","1":"32-38, 40-45, 47, 48","2":"1-13, 17-19, 21-25"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","stext":{"head":"§1997e. Suits by prisoners","paras":[[0,"(a) Applicability of administrative remedies"],[0,"No action shall be brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility until such administrative remedies as are available are exhausted."],[0,"(b) Failure of State to adopt or adhere to administrative grievance procedure"],[0,"The failure of a State to adopt or adhere to an administrative grievance procedure shall not constitute the basis for an action under section 1997a or 1997c of this title."],[0,"(c) Dismissal"],[0,"(1) The court shall on its own motion or on the motion of a party dismiss any action brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility if the court is satisfied that the action is frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief."],[0,"(2) In the event that a claim is, on its face, frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief, the court may dismiss the underlying claim without first requiring the exhaustion of administrative remedies."],[0,"(d) Attorney's fees"],[0,"(1) In any action brought by a prisoner who is confined to any jail, prison, or other correctional facility, in which attorney's fees are authorized under section 1988 1 of this title, such fees shall not be awarded, except to the extent that—"],[1,"(A) the fee was directly and reasonably incurred in proving an actual violation of the plaintiff's rights protected by a statute pursuant to which a fee may be awarded under section 1988 1 of this title; and"],[1,"(B)(i) the amount of the fee is proportionately related to the court ordered relief for the violation; or"],[1,"(ii) the fee was directly and reasonably incurred in enforcing the relief ordered for the violation."],[0,"(2) Whenever a monetary judgment is awarded in an action described in paragraph (1), a portion of the judgment (not to exceed 25 percent) shall be applied to satisfy the amount of attorney's fees awarded against the defendant. If the award of attorney's fees is not greater than 150 percent of the judgment, the excess shall be paid by the defendant."],[0,"(3) No award of attorney's fees in an action described in paragraph (1) shall be based on an hourly rate greater than 150 percent of the hourly rate established under section 3006A of title 18 for payment of court-appointed counsel."],[0,"(4) Nothing in this subsection shall prohibit a prisoner from entering into an agreement to pay an attorney's fee in an amount greater than the amount authorized under this subsection, if the fee is paid by the individual rather than by the defendant pursuant to section 1988 1 of this title."],[0,"(e) Limitation on recovery"],[0,"No Federal civil action may be brought by a prisoner confined in a jail, prison, or other correctional facility, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(f) Hearings"],[0,"(1) To the extent practicable, in any action brought with respect to prison conditions in Federal court pursuant to section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility, pretrial proceedings in which the prisoner's participation is required or permitted shall be conducted by telephone, video conference, or other telecommunications technology without removing the prisoner from the facility in which the prisoner is confined."],[0,"(2) Subject to the agreement of the official of the Federal, State, or local unit of government with custody over the prisoner, hearings may be conducted at the facility in which the prisoner is confined. To the extent practicable, the court shall allow counsel to participate by telephone, video conference, or other communications technology in any hearing held at the facility."],[0,"(g) Waiver of reply"],[0,"(1) Any defendant may waive the right to reply to any action brought by a prisoner confined in any jail, prison, or other correctional facility under section 1983 of this title or any other Federal law. Notwithstanding any other law or rule of procedure, such waiver shall not constitute an admission of the allegations contained in the complaint. No relief shall be granted to the plaintiff unless a reply has been filed."],[0,"(2) The court may require any defendant to reply to a complaint brought under this section if it finds that the plaintiff has a reasonable opportunity to prevail on the merits."],[0,"(h) \"Prisoner\" defined"],[0,"As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997e?type=usc&year=mostrecent&link-type=html"},"head":"§1997e. Suits by prisoners","tname":"The Public Health and Welfare","by":{"0":"20, 24","1":"34","2":"4, 7"}},{"t":"case","label":"Ala. Dep’t of Labor v. Barnett","cite":"341 So. 3d 1096","y":2021,"court":"Ala. Civ. App.","url":"https://www.courtlistener.com/c/So.%203d/341/1096/","by":{"1":"5"}},{"t":"case","label":"Ala. Dep’t of Revenue v. CSX Transp., Inc.","cite":"575 U.S. 21","y":2015,"id":"2014/13-553","sc":1,"sum":"The Court held that, in evaluating whether a tax is discriminatory under the Railroad Revitalization and Regulatory Reform Act of 1974, courts may consider competitors an appropriate comparison class and must examine the tax code as a whole rather than solely the challenged provision.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Alexander v. S.C. Conf. of NAACP","cite":"144 S. Ct. 1221","y":2024,"id":"2023/22-807","sc":1,"sum":"Because the District Court’s finding that race predominated in the design of South Carolina’s first congressional district was clearly erroneous, the District Court’s racial-gerrymandering and vote-dilution holdings cannot stand.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"Altria Grp. v. Good","cite":"555 U.S. 70","y":2008,"id":"2008/07-562","sc":1,"sum":"The Court held that the Federal Cigarette Labeling and Advertising Act did not preempt all claims related to \"smoking and health\" under the Maine Unfair Trade Practices Act.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Am. Dredging Co. v. Miller","cite":"510 U.S. 443","y":1994,"id":"1993/91-1950","sc":1,"sum":"The Court decided that \"forum non conveniens\" claims were only procedural, not substantive, and that national uniformity was therefore not required by the Constitution. Writing for the seven-member majority, Justice Antonin Scalia stated \"venue is a matter that goes to process rather than substantive rights -- determining which among various competent courts will decide the case.","sumSrc":"Oyez","by":{"1":"26, 36"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"1":"18, 19"}},{"t":"case","label":"Ark. Writers’ Project, Inc. v. Ragland","cite":"481 U.S. 221","y":1987,"id":"1986/85-1370","sc":1,"sum":"Arkansas imposes a tax on receipts from sales of tangible personal property, but exempts numerous items, including newspapers and \"religious, professional, trade, and sports journals and/or publications printed and published within this State\" (magazine exemption). Appellant publishes in Arkansas a general interest magazine that includes articles on a variety of subjects, including religion and sports. In 1984, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Bailey v. Cent. Vt. Ry.","cite":"319 U.S. 350","y":1943,"id":"scdb/1942-148","sc":1,"sum":"In this suit under the Federal Employers Liability Act, brought in a state court against a carrier to recover damages for the death of an employee, the evidence was sufficient to go to the jury on the question whether, as alleged in the complaint, the defendant was negligent in failing to use reasonable care to furnish the employee a safe place to work. P. 354. 113 Vt. 8, 28 A. 2d 639, reversed. CERTIORARI, 318 U. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Baker v. McCollan","cite":"443 U.S. 137","y":1979,"id":"1978/78-752","sc":1,"sum":"Respondent failed to satisfy § 1983's threshold requirement that the plaintiff be deprived of a right \"secured by the Constitution and laws,\" and hence had no claim cognizable under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Brown v. Davenport","cite":"596 U.S. 118","y":2022,"id":"2021/20-826","sc":1,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35"}},{"t":"case","label":"Brown v. Gen. Servs. Admin.","cite":"425 U.S. 820","y":1976,"id":"1975/74-768","sc":1,"sum":"Section 717 provides the exBROWN v. GSA","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Carmichael v. S. Coal & Coke Co.","cite":"301 U.S. 495","y":1937,"id":"scdb/1936-101","sc":1,"sum":"The Unemployment Compensation Act of Alabama sets up a scheme for providing unemployment benefits for workers employed within the State by designated classes of employers. These include all who employ eight or more persolns for twenty or more' weeks in the year, except those engaged in certain specified employments. The employers are to pay certain percentages of their total monthly payrolls into the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4"}},{"t":"case","label":"Chamber of Com. of U.S. v. Whiting","cite":"563 U.S. 582","y":2011,"id":"2010/09-115","sc":1,"ar":1,"sum":"The Court held that Arizona laws requiring employers to verify the employment eligibility of their employees through a federal database was not unconstitutional.","sumSrc":"Oyez","by":{"1":"18, 34"}},{"t":"case","label":"Chesapeake & Ohio Ry. v. Carnahan","cite":"241 U.S. 241","y":1916,"id":"scdb/1915-186","sc":1,"sum":"Minneapolis & St. Louis R. R. v. Bombolis, ante, p. 211, followed to effect that the contention that in trial of cases under the Employers’ Liability Act the parties are entitled under the Seventh Amendment to a common-law jury of twelve men is untenable.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"op":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Claflin v. Houseman","cite":"93 U.S. 130","y":1876,"id":"scdb/1876-027","sc":1,"sum":"This action was brought in May, 1872, in the New York Supreme Court, county of Kings, by Julius Houseman, as assignee in bankruptcy of Comstock and Young, against Horace B. Clafiin, under the thirty-fifth section of the Bankrupt Act, to recover the sum of $1,935.57, with interest, being the amount collected by Clafiin on a judgment against the bankrupts, recovered within four months before the commencement' of …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Converse v. Massachusetts","cite":"101 F.2d 48","y":1939,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/101/48/","by":{"1":"30"}},{"t":"case","label":"Cotton v. Jackson","cite":"216 F.3d 1328","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/216/1328/","ar":1,"by":{"1":"32"}},{"t":"case","label":"CSX Transp., Inc. v. Easterwood","cite":"507 U.S. 658","y":1993,"id":"1992/91-790","sc":1,"sum":"Under the FRSA, federal regulations adopted by the Secretary of Transportation pre-empt Easterwood's negligence action only insofar as it asserts that CSX's train was traveling at an excessive speed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 18"}},{"t":"case","label":"Deltona Corp. v. Alexander","cite":"682 F.2d 888","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/682/888/","by":{"1":"30"}},{"t":"case","label":"Dep’t of Indus. Relations v. Drummond","cite":"1 So. 2d 395","y":1941,"court":"Ala. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/1/395/","by":{"1":"4"}},{"t":"case","label":"Dice v. Akron, Canton & Youngstown R.R.","cite":"342 U.S. 359","y":1952,"id":"scdb/1951-039","sc":1,"sum":".1. In an action in a state court under the Federal Employers' Liability Act, the question of the validity of a release granted to the carrier by the injured employee is a federal question and is to be determined by federal rather than state law.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Dist. Attorney’s Off. for Third Jud. Dist. v. Osborne","cite":"557 U.S. 52","y":2009,"id":"2008/08-6","sc":1,"sum":"The Court found that the defendant had no constitutional right to obtain post-conviction access to DNA evidence used against him at trial.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Douglas v. N.Y., New Haven & Hartford R.R","cite":"279 U.S. 377","y":1929,"id":"scdb/1928-102","sc":1,"ar":1,"sum":"1. In determining whether the privileges and immunities clause of the Constitution, or an Act of Congress, is contravened by a state statute, the purport established for the state statute by the highest court of the State is accepted here.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 40"}},{"t":"case","label":"Evans v. Nat’l Microsystems, Inc.","cite":"576 So. 2d 207","y":1991,"court":"Ala.","url":"https://www.courtlistener.com/c/So.%202d/576/207/","by":{"1":"5"}},{"t":"case","label":"F. Hoffmann-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Fair Assessment in Real Estate Ass’n v. McNary","cite":"454 U.S. 100","y":1981,"id":"1981/80-427","sc":1,"sum":"The principle of comity bars taxpayers' damages actions brought in federal courts under 42 U. S. C. § 1983 to redress the allegedly unconstitutional administration of a state tax system. Because the principle of comity bars federal courts from granting damages relief in such cases, it is not necessary to decide whether the Tax Injunction Act, standing alone, would bar such actions.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27, 30"}},{"t":"case","label":"FCC v. RCA Commc’ns, Inc.","cite":"346 U.S. 86","y":1953,"id":"scdb/1952-103","sc":1,"sum":"Under the Federal Communications Act of 1934, the Commission authorized a radiotelegraph company, which was then serving 39 overseas points, to open two new circuits, to Portugal and The Netherlands. The authorization was opposed by another company which provided similar service by means of 65 circuits, including circuits to each of those countries. The Commission concluded that duplicate facilities should be …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"FERC v. Vitol","cite":"79 F.4th 1059","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/79/1059/","by":{"1":"15"}},{"t":"case","label":"Garrett v. Moore–McCormack, Co.","cite":"317 U.S. 239","y":1942,"id":"scdb/1942-008","sc":1,"by":{"1":"26"}},{"t":"case","label":"Gomez v. United States","cite":"490 U.S. 858","y":1989,"id":"1988/88-5014","sc":1,"sum":"A Magistrate assigned by the District Judge conducted the voir dire examination and jury selection for petitioners' trial on multiple felony counts. The judge overruled petitioners' objections to the assignment of the Magistrate. The judge offered to review any of the Magistrate's rulings de novo, but petitioners registered no specific challenge to the selection of any juror. After petitioners were convicted and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"1":"14, 47"}},{"t":"case","label":"Henderson v. Bank of New Eng.","cite":"986 F.2d 319","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/986/319/","by":{"1":"30"}},{"t":"case","label":"Herb v. Pitcairn","cite":"324 U.S. 117","y":1945,"id":"scdb/1944-123","sc":1,"ar":1,"by":{"1":"22","2":"17"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Holmgren v. United States","cite":"217 U.S. 509","y":1910,"id":"scdb/1909-152","sc":1,"sum":"The validity, under Art. I. §8^ cl. 4, of the Constitution, of the acts of Congress regulating naturalization of aliens and.authorizing naturalization proceedings in state as well as Federal courts, has never been questioned..","sumSrc":"Headnote (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Huntington v. Attrill","cite":"146 U.S. 657","y":1892,"id":"scdb/1892-054","sc":1,"sum":"A bill in equity in one State to set aside a conveyance of property made in fraud of creditors, aiyl to charge it' with' the payment ofa judgment since recovered by the plaintiff against the debtor in another State upon his liability as aji officer in a corporation under a statute of that State, set forth the judgment and the cause of action on which it was recovered; and' also asserted, independently of the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"48","2":"8"}},{"t":"case","label":"Jones v. Rath Packing Co.","cite":"430 U.S. 519","y":1977,"id":"1976/75-1053","sc":1,"sum":"Section 12211 of the California Business and Professions Code provides that \"the average weight or measure of the packages or containers in a lot of any... commodity sampled shall not be less, at the time of sale or offer for sale, than the net weight or measure stated upon the package.\" Article 5, § 2930 et seq., of Title 4 of the California Administrative Code in implementing § 12211 requires a statistical …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Kansas v. Garcia","cite":"589 U.S. 191","y":2020,"id":"2019/17-834","sc":1,"op":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"1":"14, 15, 18, 19"}},{"t":"case","label":"Marrese v. Am. Acad. of Ortho. Surgeons","cite":"470 U.S. 373","y":1985,"id":"1984/83-1452","sc":1,"sum":"After being denied membership in respondent American Academy of Orthopaedic Surgeons, petitioner orthopaedic surgeons each filed an action in an Illinois Circuit Court, alleging that the denial of membership violated their associational rights under Illinois common law. After the Illinois Appellate Court ultimately held that the complaint in one action failed to state a cause of action, the Circuit Court then …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Martinez v. California","cite":"444 U.S. 277","y":1980,"id":"1979/78-1268","sc":1,"sum":"The Court held that a statute immunizing parole officials from injuries resulting from parole decisions violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"44","2":"2"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"op":1,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"McKart v. United States","cite":"395 U.S. 185","y":1969,"id":"1968/403","sc":1,"sum":"Petitioner had been classified IV-A (sole surviving son status). When the Selective Service Board learned of the death of petitioner's mother, it reclassified him I-A (available for military service), on the theory that the IV-A classification became improper when the \"family unit\" ceased to exist. Petitioner did not appeal the reclassification. Upon his failure to report as ordered for his pre-induction physical …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27, 30"}},{"t":"case","label":"McKnett v. St. Louis & S.F. Ry.","cite":"292 U.S. 230","y":1934,"id":"scdb/1933-122","sc":1,"op":2,"sum":"The Federal Constitution forbids that a State should clo~e its courts to transitory causes of action against foreign corporations arising in other States under federal law (Federal Employers' Liability Act) while opening them to the litigation of all like transitory causes arising in other States under state law. P. 232. 227 Ala. 349; 149 So. 822, reversed. CERTIORARI, 290 U.S. 621, to review the affirmance of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Miles v. Ill. Cent. R.R.","cite":"315 U.S. 698","y":1942,"id":"scdb/1941-143","sc":1,"sum":"Section 6 of the Federal Employers' Liability Act prevents a state court from enjoining, on the ground of the inconvenience or expense to the railroad, a resident citizen of the State from prosecuting or furthering an action under the Act (or receiving the proceeds of any judgment therein) in a state court of another State which has jurisdiction under the Act. P. 705. Reversed. CERTIORARI, 314 U. S. 602, to review a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Minneapolis & St. Louis R.R. v. Bombolis","cite":"241 U.S. 211","y":1916,"id":"scdb/1915-182","sc":1,"sum":"The Seventh Amendment exacts a trial by jury according to the course of the common law, that is, by a unanimous verdict.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Missouri ex rel. S. Ry. v. Mayfield","cite":"340 U.S. 1","y":1950,"id":"scdb/1950-001","sc":1,"sum":"The judgment is vacated and the cause is remanded, in order that the State Supreme Court may determine the availability of the principle of forum non conveniens according to its own local law. Pp. 2-3, 5.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Missouri v. Lewis","cite":"101 U.S. 22","y":1879,"id":"scdb/1879-170","sc":1,"sum":"This writ of error was brought by the State of Missouri, on the relation of Frank J. Bowman, to reverse the judgment of the Supreme Court of Missouri refusing to issue a mandamus to Edward A. Lewis, Charles S. Hayden, and Robert A. Bakewell, judges of the Saint Louis Court of Appeals. The object of the mandamus was to compel the latter court to grant his application for an appeal to the said Supreme Court from a …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Mondou v. N.Y., New Haven & Hartford R.R.","cite":"223 U.S. 1","y":1912,"id":"scdb/1911-127","sc":1,"ar":1,"sum":"The Employers’ Liability Act of April 22, 1908, 35 Stat. 65, c.149, as amended April 5, 1910, 36 Stat. 291, c. 143, regulating the liability of common carriers.by railroad to their employés,¡¡s constitutional.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Murray v. Reif","cite":"36 A.D.3d 1167","y":2007,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D.3d/36/1167/","by":{"1":"28"}},{"t":"case","label":"Myers v. Bethlehem Shipbuilding Corp.","cite":"303 U.S. 41","y":1938,"id":"scdb/1937-127","sc":1,"sum":"(1) That the District Court had no jurisdiction of a suit by the corpdration to enjoin the Board from holding the hearing. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"N.J. Payphone Ass’n v. Town of W. N.Y.","cite":"299 F.3d 235","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/299/235/","by":{"1":"18"}},{"t":"case","label":"N.Y. State Conf. of Blue Cross & Blue Shield Plans v. Travelers Ins. Co.","cite":"514 U.S. 645","y":1995,"id":"1994/93-1408","sc":1,"sum":"New York's surcharge provisions do not \"relate to\" employee benefit plans within the meaning of § 514(a) and, thus, are not pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Nat’l Priv. Truck Council, Inc. v. Okla. Tax Comm’n","cite":"515 U.S. 582","y":1995,"id":"1994/94-688","sc":1,"sum":"In the Oklahoma state taxes as state courts, violating the petitioners \"dormant\" successfully challenged certain Commerce Clause. The Oklahoma Supreme Court ordered respondents to award refunds pursuant to state law, but declined to award declaratory or injunctive relief under 42 U. S. C. §1983 or attorney's fees under §1988. The court reasoned that because adequate remedies existed under state law, the Tax …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Nicol v. Ames","cite":"173 U.S. 509","y":1899,"id":"scdb/1898-108","sc":1,"sum":"Decided April 3, 1899.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"597 U.S. 629","y":2022,"id":"2021/21-429","sc":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"14, 17, 18"}},{"t":"case","label":"Osborn v. Bank of U.S.","cite":"22 U.S. 738","y":1824,"id":"1789-1850/22us738","sc":1,"sum":"In a 6-to-1 decision, the Court held that the circuit court properly ruled against Ohio officials and that the Ohio law was \"repugnant to the Constitution.\" The Court held that the Eleventh Amendment was limited to suits in which a state was party on the record, and that Ohio was not the target of the suit in the case at hand.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Pac. Gas & Elec. Co. v. State Energy Res. Conservation & Dev. Comm’n","cite":"461 U.S. 190","y":1983,"id":"1982/81-1945","sc":1,"sum":"The Court held that the California law did not impinge upon congressional authority. The Court found that because the rationale for enacting the law was an economic one, it did not interfere with federal regulations governing nuclear safety.","sumSrc":"Oyez","by":{"1":"13, 31"}},{"t":"case","label":"Parisi v. Davidson","cite":"405 U.S. 34","y":1972,"id":"1971/70-91","sc":1,"sum":"The District Court should not have stayed its hand in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Perez v. Campbell","cite":"402 U.S. 637","y":1971,"id":"1970/5175","sc":1,"sum":"The provision that \"discharge in bankruptcy following the rendering of any such judgment [as a result of an automobile accident] shall not relieve the judgment debtor from any of the requirements of this article,\" contained in Ariz. Rev. Stat. § 28-1163 (B), part of the Motor Vehicle Safety Responsibility Act, which the Arizona courts have construed as having as \"its principal purpose the protection of the public …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Pontius v. State Farm. Mut. Auto. Ins. Co.","cite":"915 So. 2d 557","y":2005,"court":"Ala.","url":"https://www.courtlistener.com/c/So.%202d/915/557/","by":{"1":"24"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Prigg v. Pennsylvania","cite":"41 U.S. 539","y":1842,"id":"1789-1850/41us539","sc":1,"sum":"Yes and yes. Justice Joseph Story delivered the opinion of the Court. The 1788 and 1826 Pennsylvania laws contradicted Article IV, Section 2 of the Constitution and the Fugitive Slave Law. The Supremacy Clause assured that federal laws prevailed over the state laws. The decision did not wholly end asylum across state lines for slaves.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"1":"13, 44"}},{"t":"case","label":"Quern v. Jordan","cite":"440 U.S. 332","y":1979,"id":"1978/77-841","sc":1,"sum":"In Edelman v. Jordan, 415 U. S. 651, it was held that retroactive welfare benefits awarded by a Federal District Court to the plaintiff class, by reason of wrongful denial of benefits by Illinois officials prior to the entry of the court's order determining the wrongfulness of their actions, violated the Eleventh Amendment, and that in an action under 42 U. S. C. § 1983 \"a federal court's remedial power, consistent …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"R. J. Reynolds Tobacco Co. v. Durham County","cite":"479 U.S. 130","y":1986,"id":"1986/85-1021","sc":1,"sum":"Appellant, a New Jersey corporation with its principal office and only manufacturing facilities located in North Carolina, blends tobacco imported from foreign countries with domestic tobacco in producing finished tobacco products virtually all of which are consumed in the United States. Upon importation, the foreign tobacco is placed under customs bond given by appellant, and is stored in one or more of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Reetz v. Michigan","cite":"188 U.S. 505","y":1903,"id":"scdb/1902-067","sc":1,"sum":"A State' has power to make reasonable provisions for determining the qualifications of those engaged in the practice of medicine and for punishing those who attempt to engage therein in defiance of such statutory provisions.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Rice v. Santa Fe Elevator Corp.","cite":"331 U.S. 218","y":1947,"id":"scdb/1946-098","sc":1,"op":1,"sum":"1. By the 1931 amendments to §§ 6 and 29 of the United States Warehouse Act, Congress terminated the dual system of regulation provided by the original Act and substituted an exclusive system of federal regulation of warehouses licensed under the Federal Act with reference to the subjects covered thereby, except to the extent that express exceptions in the Federal Act subject certain phases of the business to state …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 18"}},{"t":"case","label":"Rizzo v. Goode","cite":"423 U.S. 362","y":1976,"id":"1975/74-942","sc":1,"sum":"Two suits, permitted to proceed as class actions, were brought in District Court under 42 U. S. C. § 1983 by respondents, individuals and organizations, against petitioners, the Mayor of Philadelphia, the Police Commissioner, and others, alleging a pervasive pattern of illegal and unconstitutional police mistreatment of minority citizens in particular and Philadelphia residents in general. The petitioners were …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Shady Grove Ortho. Assocs. v. Allstate Ins. Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"sum":"The Court held that Section 901(b) of the New York Rules of Civil Procedure does not preclude a federal court ruling on entities from different jurisdictions from hearing a class action under Rule 23 of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Tenn. Coal, Iron & R.R. v. Martin","cite":"36 So. 2d 547","y":1948,"court":"Ala.","url":"https://www.courtlistener.com/c/So.%202d/36/547/","by":{"1":"3"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"37"}},{"t":"case","label":"United States v. Coombs","cite":"37 U.S. 72","y":1838,"id":"scdb/1838-003","sc":1,"sum":"Indictment in thecircuit court of the United, States for the southern district of New York, for feloniously stealing a quantity of meYchandise belonging' to the ship Bristol, the ship being-in distress and cast away on a shoal of the seá oh the ociast,of the state of New 'York. The indictment was founded on the 9th section of.tbe^ act, entitled “ An Act.more effectually to provide for the punishment of certain …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"United States v. Jones","cite":"109 U.S. 513","y":1883,"id":"scdb/1883-070","sc":1,"sum":"Conflict of Laws — Constitutional Law — Damages—JEminent Domain — State Courts.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Va. Uranium, Inc. v. Warren","cite":"587 U.S. 761","y":2019,"url":"https://supreme.justia.com/cases/federal/us/587/761/","sc":1,"by":{"1":"16-20, 31, 35"}},{"t":"case","label":"Vance v. Montgomery Cnty. Dep’t of Human Res.","cite":"693 So. 2d 493","y":1997,"court":"Ala. Civ. App.","url":"https://www.courtlistener.com/c/So.%202d/693/493/","op":1,"by":{"1":"5, 21, 26"}},{"t":"case","label":"Wilson v. Garcia","cite":"471 U.S. 261","y":1985,"id":"1984/83-2146","sc":1,"sum":"The Court held that, in situations where a federal action does not have a statute of limitations, the practice has been to adopt a local limitation as long as that limitation is not inconsistent with a federal law or policy.","sumSrc":"Oyez","by":{"1":"26","2":"3"}},{"t":"case","label":"Wilson v. New","cite":"243 U.S. 332","y":1917,"id":"scdb/1916-143","sc":1,"sum":"The effect of the Act of September 3, 5, 1916, entitled “An Act to establish an eight-hour day for employees of carriers engaged in interstate and foreign commerce, and for other purposes,” c. 436, 39 Stat. 721, is not only to establish permanently an eight-hour standard for work and wages as between the carriers and employees affected, but also to fix a scale of minimum wages, to wit, the rate of wages then …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that a prisoner must properly exhaust any available administrative remedies before bringing suit in federal court. This understanding of the PLRA's exhaustion provision mirrors that of the traditional exhaustion provision in administrative law and is \"substantively similar\" to that of habeas corpus law.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"op":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"1":"17-19, 35"}},{"t":"case","label":"Zinermon v. Burch","cite":"494 U.S. 113","y":1990,"id":"1989/87-1965","sc":1,"sum":"Burch's complaint was sufficient to state a claim under § 1983 for violation of his procedural due process rights. While Parrattand Hudson apply to deprivations of liberty, they do not preclude Burch's claim, because predeprivation procedural safeguards might have been of value in preventing the alleged deprivation of Burch's liberty without either valid consent or an involuntary placement hearing. Such a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"usc","label":"12 U.S.C. § 1821","url":"https://www.law.cornell.edu/uscode/text/12/1821","subs":["(d)(13)(D)"],"by":{"1":"30"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","by":{"1":"30"}},{"t":"usc","label":"28 U.S.C. § 2462","url":"https://www.law.cornell.edu/uscode/text/28/2462","by":{"1":"15"}},{"t":"usc","label":"42 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/42/501","by":{"1":"7"}},{"t":"usc","label":"42 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/42/502","by":{"1":"7"}},{"t":"usc","label":"42 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/42/1101","subs":["(c)(1)"],"by":{"1":"7"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","by":{"1":"30"}},{"t":"reg","label":"20 C.F.R. § 640.3","url":"https://www.ecfr.gov/current/title-20/section-640.3","by":{"1":"7"}},{"t":"case","label":"Monell v. New York City Department of Social Services","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Orthmann v. Apple River Campground, Inc.","cite":"757 F.2d 909","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/757/909/","by":{"2":"20"}},{"t":"case","label":"Terrell v. City of Bessemer","cite":"406 So. 2d 337","y":1981,"court":"Ala.","url":"https://www.courtlistener.com/c/So.%202d/406/337/","by":{"2":"22"}}]};